def optimal_string(N, A, B):
    S = [''] * (2 * N)
    A = list(A)
    B = list(B)
    turn = 0  # 0 for Alice, 1 for Bob

    while A or B:
        if turn == 0:  # Alice's turn
            if A and (not B or A[0] <= B[0]):
                char = A.pop(0)
            else:
                char = B.pop(0)
        else:  # Bob's turn
